"use client";

import { useEffect, useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { BlockFrame } from "../parts/block-frame";
import { InfoIcon } from "./shared/icons";
import { formatCount, plural } from "./shared/money";
import { Reveal } from "./shared/reveal";
import {
  AVATAR_FILLS,
  type Invite,
  INVITES,
  MEMBERS,
  PURCHASED,
  RENEWS,
  SEAT_PRICE,
} from "./seat-manager/data";
import { InviteList } from "./seat-manager/invite-list";
import { type ChangePhase, SeatChange } from "./seat-manager/seat-change";
import { SeatMeter } from "./seat-manager/seat-meter";

/** A revoked invite that can still come back, with the place it held. */
interface Revoked {
  invite: Invite;
  index: number;
}

/**
 * The seats and billing card of a Fernhill clinic: who holds a seat, how many
 * are open, a stepper that prices a change before anyone is charged, and the
 * pending invites with Resend and Revoke. A revoke can be undone.
 */
export function SeatManager({ className }: { className?: string }) {
  const titleId = useId();
  const [purchased, setPurchased] = useState(PURCHASED);
  const [target, setTarget] = useState(PURCHASED);
  const [phase, setPhase] = useState<ChangePhase>("edit");
  const [invites, setInvites] = useState(INVITES);
  const [resent, setResent] = useState<string[]>([]);
  const [revoked, setRevoked] = useState<Revoked | null>(null);
  const [notice, setNotice] = useState("");
  const timers = useRef<number[]>([]);
  useEffect(
    () => () => timers.current.forEach((timer) => window.clearTimeout(timer)),
    [],
  );

  const later = (run: () => void, ms: number) => {
    timers.current.push(window.setTimeout(run, ms));
  };

  const used = MEMBERS.length + invites.length;
  const open = Math.max(0, Math.min(purchased, target) - used);
  const added = Math.max(0, target - purchased);
  const full = used >= purchased && target === purchased;

  const changeTarget = (seats: number) => {
    if (phase === "saving") return;
    setTarget(seats);
    setPhase("edit");
  };

  const confirm = () => {
    setPhase("saving");
    later(() => {
      setPurchased(target);
      setPhase("edit");
      setNotice(`Your plan now has ${plural(target, "seat")}.`);
    }, 1000);
  };

  const revoke = (email: string) => {
    const index = invites.findIndex((item) => item.email === email);
    const invite = invites[index];
    if (!invite) return;
    setInvites((list) => list.filter((item) => item.email !== email));
    setRevoked({ invite, index });
    setNotice(`Invite to ${email} revoked. Its seat is open again.`);
  };

  const undo = () => {
    if (!revoked) return;
    setInvites((list) => [
      ...list.slice(0, revoked.index),
      revoked.invite,
      ...list.slice(revoked.index),
    ]);
    setNotice(`Invite to ${revoked.invite.email} restored.`);
    setRevoked(null);
  };

  const resend = (email: string) => {
    setResent((list) => [...list, email]);
    setNotice(`Invite sent again to ${email}.`);
    later(
      () => setResent((list) => list.filter((item) => item !== email)),
      2500,
    );
  };

  const shown = MEMBERS.slice(0, 5);

  return (
    <BlockFrame
      aria-labelledby={titleId}
      className={cn("mx-auto max-w-xl", className)}
    >
      <div className="flex flex-col gap-5 p-5">
        <header className="flex flex-col gap-1">
          <h2 id={titleId} className="text-lg font-semibold">
            Seats
          </h2>
          <p className="text-sm text-muted-foreground">
            Harbour Street Clinic, Practice plan, ${SEAT_PRICE} a seat a month,
            renews {RENEWS}
          </p>
        </header>

        <div className="flex flex-wrap items-center justify-between gap-3">
          <ul
            className="flex"
            aria-label={`Members: ${MEMBERS.map((item) => item.name).join(", ")}`}
          >
            {shown.map((member, index) => (
              <li
                key={member.name}
                aria-hidden="true"
                className={cn(
                  "-ml-1.5 grid size-8 place-items-center rounded-full text-xs font-semibold text-primary-foreground ring-2 ring-card first:ml-0",
                  AVATAR_FILLS[index % AVATAR_FILLS.length],
                )}
              >
                {member.initials}
              </li>
            ))}
            <li
              aria-hidden="true"
              className="-ml-1.5 grid size-8 place-items-center rounded-full bg-muted text-xs font-medium ring-2 ring-card"
            >
              +{MEMBERS.length - shown.length}
            </li>
          </ul>
          <p className="text-sm">
            <span className="font-semibold tabular-nums">
              {formatCount(used)} of {formatCount(purchased)}
            </span>{" "}
            <span className="text-muted-foreground">seats used</span>
          </p>
        </div>

        <SeatMeter
          members={MEMBERS.length}
          invited={invites.length}
          open={open}
          added={added}
        />

        <Reveal show={full}>
          <div className="flex flex-wrap items-center gap-3 rounded-xl bg-marketing-amber-surface px-3 py-2.5 text-sm text-marketing-amber-ink">
            <InfoIcon aria-hidden="true" className="size-4 shrink-0" />
            <span className="min-w-0 flex-1">
              Every seat is taken. Add one before you invite anyone else.
            </span>
            <Button
              type="button"
              size="sm"
              variant="outline"
              onClick={() => changeTarget(purchased + 1)}
            >
              Add a seat
            </Button>
          </div>
        </Reveal>

        <div className="border-t border-border pt-5">
          <SeatChange
            purchased={purchased}
            target={target}
            used={used}
            phase={phase}
            onTargetChange={changeTarget}
            onReview={() => setPhase("review")}
            onBack={() => setPhase("edit")}
            onConfirm={confirm}
          />
        </div>

        <section
          aria-labelledby={`${titleId}-invites`}
          className="border-t border-border pt-4"
        >
          <h3 id={`${titleId}-invites`} className="text-sm font-medium">
            Pending invites{" "}
            <span className="text-muted-foreground tabular-nums">
              {invites.length}
            </span>
          </h3>
          <InviteList
            invites={invites}
            resent={resent}
            onResend={resend}
            onRevoke={revoke}
          />
        </section>

        <div className="flex min-h-9 flex-wrap items-center justify-between gap-2 text-sm">
          <p aria-live="polite" className="text-muted-foreground">
            {notice}
          </p>
          {revoked && used < purchased ? (
            <Button type="button" variant="outline" size="sm" onClick={undo}>
              Undo revoke
            </Button>
          ) : null}
        </div>
      </div>
    </BlockFrame>
  );
}

