"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";

import { CheckIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";

import { MailIcon } from "../shared/icons";
import type { Invite } from "./data";

const HEIGHT: Transition = {
  type: "spring",
  stiffness: 420,
  damping: 42,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

/** Props for the pending invite list. */
export interface InviteListProps {
  invites: Invite[];
  /** Emails whose invite was just sent again. */
  resent: string[];
  onResend: (email: string) => void;
  onRevoke: (email: string) => void;
}

/**
 * The invitations still waiting, each with who sent it and when, and a
 * Resend and a Revoke action. A revoked row closes its height.
 */
export function InviteList({
  invites,
  resent,
  onResend,
  onRevoke,
}: InviteListProps) {
  const reduceMotion = useReducedMotion();
  return (
    <ul className="flex flex-col" aria-label="Pending invites">
      <AnimatePresence initial={false}>
        {invites.map((invite) => {
          const sent = resent.includes(invite.email);
          return (
            <motion.li
              key={invite.email}
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: "auto", opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={reduceMotion ? INSTANT : HEIGHT}
              className="overflow-hidden"
            >
              <div className="flex flex-wrap items-center gap-x-3 gap-y-2 py-2.5">
                <span
                  aria-hidden="true"
                  className="grid size-8 shrink-0 place-items-center rounded-full bg-chart-3 text-primary-foreground"
                >
                  <MailIcon className="size-4" />
                </span>
                <span className="flex min-w-0 flex-1 flex-col text-sm">
                  <span className="truncate font-medium">{invite.email}</span>
                  <span className="text-xs text-muted-foreground">
                    Invited by {invite.invitedBy}, {invite.when}
                  </span>
                </span>
                <span className="ml-auto flex gap-1">
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    aria-disabled={sent}
                    aria-label={
                      sent
                        ? `Invite sent again to ${invite.email}`
                        : `Resend invite to ${invite.email}`
                    }
                    onClick={() => {
                      if (!sent) onResend(invite.email);
                    }}
                  >
                    {sent ? <CheckIcon aria-hidden="true" /> : null}
                    {sent ? "Sent" : "Resend"}
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    size="sm"
                    aria-label={`Revoke invite to ${invite.email}`}
                    onClick={() => onRevoke(invite.email)}
                  >
                    Revoke
                  </Button>
                </span>
              </div>
            </motion.li>
          );
        })}
      </AnimatePresence>
      {invites.length === 0 ? (
        <li className="py-3 text-sm text-muted-foreground">
          No invites are waiting.
        </li>
      ) : null}
    </ul>
  );
}

"use client";

import { useEffect, useRef } from "react";

import { RollingText } from "@/components/blocks/parts/rolling-text";
import { Button } from "@/components/ui/button";

import { LoaderIcon } from "../shared/icons";
import { formatCents, plural } from "../shared/money";
import { Reveal } from "../shared/reveal";
import { Stepper } from "../shared/stepper";
import {
  CYCLE_DAYS,
  DAYS_LEFT,
  MAX_SEATS,
  proratedCharge,
  RENEWS,
  SEAT_PRICE,
} from "./data";

/** Where a seat change stands. */
export type ChangePhase = "edit" | "review" | "saving";

/** Props for the seat change panel. */
export interface SeatChangeProps {
  purchased: number;
  target: number;
  /** Seats held by members and invites. The count cannot drop below it. */
  used: number;
  phase: ChangePhase;
  onTargetChange: (seats: number) => void;
  onReview: () => void;
  onBack: () => void;
  onConfirm: () => void;
}

/**
 * Sets the seat count, then shows the prorated charge due today and the new
 * monthly total beside the old one. A change goes through a review step that
 * names the charge before anyone pays it.
 */
export function SeatChange({
  purchased,
  target,
  used,
  phase,
  onTargetChange,
  onReview,
  onBack,
  onConfirm,
}: SeatChangeProps) {
  const diff = target - purchased;
  const today = proratedCharge(diff);
  const confirmRef = useRef<HTMLButtonElement | null>(null);
  const reviewRef = useRef<HTMLButtonElement | null>(null);
  const previous = useRef(phase);

  // The review step takes focus to its confirm button, and going back returns it to Review.
  useEffect(() => {
    if (phase === "review") confirmRef.current?.focus();
    if (phase === "edit" && previous.current === "review")
      reviewRef.current?.focus();
    previous.current = phase;
  }, [phase]);

  const summary =
    diff > 0
      ? `Add ${plural(diff, "seat")}. Fernhill charges ${formatCents(today)} to Visa ending 4242 today, then ${formatCents(target * SEAT_PRICE)} a month from ${RENEWS}.`
      : `Remove ${plural(-diff, "seat")}. Nothing is charged today. From ${RENEWS} the plan costs ${formatCents(target * SEAT_PRICE)} a month.`;

  return (
    <div className="flex flex-col gap-4">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="text-sm">
          <p className="font-medium">Seats on the plan</p>
          <p className="text-xs text-muted-foreground">
            {plural(purchased, "seat")} paid for now
          </p>
        </div>
        <Stepper
          label="Seats on the plan"
          unit="seats"
          value={target}
          onValueChange={onTargetChange}
          min={used}
          max={MAX_SEATS}
        />
      </div>

      <dl className="flex flex-col gap-2 text-sm" aria-live="polite">
        <div className="flex items-baseline justify-between gap-4">
          <dt className="text-muted-foreground">
            Due today
            <span className="block text-xs">
              Prorated for {DAYS_LEFT} of {CYCLE_DAYS} days
            </span>
          </dt>
          <dd className="font-medium">
            <RollingText text={formatCents(today)} />
          </dd>
        </div>
        <div className="flex items-baseline justify-between gap-4">
          <dt className="text-muted-foreground">
            From {RENEWS}
            {diff !== 0 ? (
              <span className="block text-xs">
                Was {formatCents(purchased * SEAT_PRICE)} a month
              </span>
            ) : null}
          </dt>
          <dd className="font-medium">
            <RollingText text={formatCents(target * SEAT_PRICE)} />
            <span className="text-muted-foreground"> a month</span>
          </dd>
        </div>
      </dl>

      <Reveal show={phase !== "edit" && diff !== 0}>
        <div
          role="group"
          aria-label="Review the seat change"
          className="flex flex-col gap-3 rounded-xl border border-chart-1 p-4"
        >
          <p className="text-sm">{summary}</p>
          <div className="flex flex-wrap justify-end gap-2">
            <Button
              type="button"
              variant="ghost"
              onClick={onBack}
              disabled={phase === "saving"}
            >
              Back
            </Button>
            <Button
              ref={confirmRef}
              type="button"
              aria-disabled={phase === "saving"}
              onClick={() => phase === "review" && onConfirm()}
            >
              {phase === "saving" ? (
                <LoaderIcon
                  aria-hidden="true"
                  className="motion-safe:animate-spin"
                />
              ) : null}
              {phase === "saving"
                ? "Updating seats"
                : diff > 0
                  ? `Pay ${formatCents(today)} and add seats`
                  : "Remove seats"}
            </Button>
          </div>
        </div>
      </Reveal>

      {phase === "edit" ? (
        <div className="flex flex-wrap justify-end gap-2">
          <Button
            type="button"
            variant="ghost"
            disabled={diff === 0}
            onClick={() => onTargetChange(purchased)}
          >
            Reset
          </Button>
          <Button
            ref={reviewRef}
            type="button"
            disabled={diff === 0}
            onClick={onReview}
          >
            Review change
          </Button>
        </div>
      ) : null}
    </div>
  );
}

import { NumberTicker } from "@/components/motion/number-ticker";
import { cn } from "@/lib/utils";

/** Props for a formatted figure whose digits roll. */
export interface RollingTextProps {
  /** A figure that is already formatted, such as "$3,577" or "8.2 min". */
  text: string;
  className?: string;
}

/**
 * Shows a formatted figure and rolls each digit to its new value when the
 * text changes, as a counter does. Signs, separators and units stay still.
 * Each glyph is keyed by its place from the right, so a digit keeps its
 * column when the figure grows. It is for text that already has another
 * spoken source: the rolling columns are hidden from screen readers.
 */
export function RollingText({ text, className }: RollingTextProps) {
  const glyphs = [...text];
  return (
    <span className={cn("inline-flex tabular-nums", className)}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="inline-flex">
        {glyphs.map((glyph, index) => {
          const place = glyphs.length - 1 - index;
          return glyph >= "0" && glyph <= "9" ? (
            <NumberTicker key={place} value={Number(glyph)} />
          ) : (
            <span key={place} className="whitespace-pre">
              {glyph}
            </span>
          );
        })}
      </span>
    </span>
  );
}

"use client";

import type { KeyboardEvent } from "react";

import { PlusIcon } from "@/components/blocks/parts/icons";
import { RollingText } from "@/components/blocks/parts/rolling-text";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { formatCount } from "./money";
import { MinusIcon } from "./icons";

/** Props for a count with minus and plus buttons. */
export interface StepperProps {
  value: number;
  onValueChange: (value: number) => void;
  min: number;
  max: number;
  /** Names the count, such as "Seats". */
  label: string;
  /** How far Page Up and Page Down move. */
  pageStep?: number;
  /** Spoken with the count, such as "seats". */
  unit?: string;
  className?: string;
}

/**
 * A count between two limits. The minus and plus buttons step by one, and the
 * count itself is a spin button: arrows step by one, Page keys by more, Home
 * and End go to the limits. The digits roll as the count changes.
 */
export function Stepper({
  value,
  onValueChange,
  min,
  max,
  label,
  pageStep = 5,
  unit,
  className,
}: StepperProps) {
  const set = (next: number) =>
    onValueChange(Math.min(max, Math.max(min, next)));

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const moves = new Map([
      ["ArrowUp", value + 1],
      ["ArrowRight", value + 1],
      ["ArrowDown", value - 1],
      ["ArrowLeft", value - 1],
      ["PageUp", value + pageStep],
      ["PageDown", value - pageStep],
      ["Home", min],
      ["End", max],
    ]);
    const next = moves.get(event.key);
    if (next === undefined) return;
    event.preventDefault();
    set(next);
  };

  return (
    <div
      className={cn(
        "inline-flex items-center gap-1 rounded-full border border-border bg-background p-1",
        className,
      )}
    >
      <Button
        type="button"
        variant="ghost"
        size="icon"
        className="size-8"
        aria-label={`Remove one from ${label.toLowerCase()}`}
        disabled={value <= min}
        onClick={() => set(value - 1)}
      >
        <MinusIcon aria-hidden="true" />
      </Button>
      <div
        role="spinbutton"
        tabIndex={0}
        aria-label={label}
        aria-valuenow={value}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuetext={unit ? `${formatCount(value)} ${unit}` : undefined}
        onKeyDown={onKeyDown}
        className="flex min-w-10 cursor-default justify-center rounded-md px-1 text-base font-semibold outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        <RollingText text={formatCount(value)} />
      </div>
      <Button
        type="button"
        variant="ghost"
        size="icon"
        className="size-8"
        aria-label={`Add one to ${label.toLowerCase()}`}
        disabled={value >= max}
        onClick={() => set(value + 1)}
      >
        <PlusIcon aria-hidden="true" />
      </Button>
    </div>
  );
}

"use client";

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type Transition,
} from "motion/react";

import { cn } from "@/lib/utils";

import { formatCount } from "../shared/money";

type CellKind = "member" | "invited" | "open" | "new";

const CELL = {
  member: "bg-chart-1",
  invited: "bg-chart-3",
  open: "border border-muted-foreground/40",
  new: "border border-dashed border-chart-2 bg-chart-2/25",
} satisfies Record<CellKind, string>;

const NAMES = {
  member: "members",
  invited: "invited",
  open: "open",
  new: "new",
} satisfies Record<CellKind, string>;

// Cells grow and shrink with no bounce: the meter reports a count, it does not celebrate it.
const GROW: Transition = {
  type: "spring",
  stiffness: 520,
  damping: 50,
  mass: 1,
};
const INSTANT: Transition = { duration: 0 };

/** Props for the seat meter. */
export interface SeatMeterProps {
  members: number;
  invited: number;
  /** Seats paid for and still free. */
  open: number;
  /** Seats the pending change adds. */
  added: number;
}

/**
 * One cell per seat: members, invited, open and new seats in order, with a
 * legend that counts each kind. Cells grow in from zero width and shrink out,
 * and their neighbours glide to make room.
 */
export function SeatMeter({ members, invited, open, added }: SeatMeterProps) {
  const reduceMotion = useReducedMotion();
  const counts = {
    member: members,
    invited,
    open,
    new: added,
  } satisfies Record<CellKind, number>;
  const kinds: CellKind[] = ["member", "invited", "open", "new"];
  const cells = kinds.flatMap((kind) =>
    Array.from({ length: counts[kind] }, () => kind),
  );

  return (
    <div className="flex flex-col gap-2">
      <div
        role="img"
        aria-label={`Seat meter: ${formatCount(members)} members, ${formatCount(invited)} invited, ${formatCount(open)} open, ${formatCount(added)} new.`}
        className="flex flex-wrap gap-y-1"
      >
        <AnimatePresence initial={false}>
          {cells.map((kind, index) => (
            <motion.span
              // Cells are keyed by position, so a cell that changes kind recolours in place.
              key={index}
              initial={{ width: 0, marginRight: 0, opacity: 0 }}
              animate={{
                width: "1.125rem",
                marginRight: "0.25rem",
                opacity: 1,
              }}
              exit={{ width: 0, marginRight: 0, opacity: 0 }}
              transition={reduceMotion ? INSTANT : GROW}
              className={cn(
                "block h-6 shrink-0 rounded-md motion-safe:transition-colors",
                CELL[kind],
              )}
            />
          ))}
        </AnimatePresence>
      </div>
      <ul
        className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground"
        aria-hidden="true"
      >
        {kinds.map((kind) =>
          kind === "new" && added === 0 ? null : (
            <li key={kind} className="flex items-center gap-1.5">
              <span className={cn("size-2.5 rounded-sm", CELL[kind])} />
              {formatCount(counts[kind])} {NAMES[kind]}
            </li>
          ),
        )}
      </ul>
    </div>
  );
}
